package com.salvagesack;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Manages loading and accessing expected drop rates from configuration
 */
@Slf4j
public class DropRateManager
{
	private final Map<ShipwreckType, Map<String, Double>> dropRates = new HashMap<>();
	private final Map<ShipwreckType, Map<String, Double>> displayItemRates = new HashMap<>();
	private final Gson gson;
	private final File userConfigFile;
	private JsonObject bundledRoot;

	public DropRateManager(File dataDirectory, Gson gson)
	{
		this.gson = gson;
		this.userConfigFile = new File(dataDirectory, "drop_rates.json");
		loadDropRates();
	}

	/**
	 * Load drop rates from bundled resource and user config
	 */
	private void loadDropRates()
	{
		loadBundledRates();

		if (userConfigFile.exists())
		{
			try
			{
				migrateUserConfigIfNeeded();
			}
			catch (Exception e)
			{
				log.warn("Failed to migrate user drop rates config: {}", e.getMessage());
			}
			loadUserRates();
		}
		else
		{
			copyBundledToUser();
		}
	}

	/**
	 * Load rates from bundled resource
	 */
	private void loadBundledRates()
	{
		try (InputStream is = getClass().getResourceAsStream("/drop_rates.json"))
		{
			if (is != null)
			{
				try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
				{
					bundledRoot = gson.fromJson(reader, JsonObject.class);
					parseDropRatesFromObject(bundledRoot);
					log.info("Loaded bundled drop rates");
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load bundled drop rates: {}", e.getMessage());
		}
	}

	/**
	 * Migrate user configuration if it is from an older version than bundled defaults.
	 * Preserves intentional user customizations while refreshing default rates and adding new items.
	 */
	private void migrateUserConfigIfNeeded()
	{
		if (bundledRoot == null)
		{
			return;
		}

		int bundledVersion = bundledRoot.has("version") ? bundledRoot.get("version").getAsInt() : 1;
		JsonObject userRoot = null;
		try (InputStreamReader reader = new InputStreamReader(new FileInputStream(userConfigFile), StandardCharsets.UTF_8))
		{
			userRoot = gson.fromJson(reader, JsonObject.class);
		}
		catch (Exception e)
		{
			log.warn("Failed to read user drop rates config for migration check: {}", e.getMessage());
			return;
		}

		if (userRoot == null)
		{
			return;
		}

		int userVersion = userRoot.has("version") ? userRoot.get("version").getAsInt() : 1;
		if (userVersion >= bundledVersion)
		{
			return;
		}

		log.info("Migrating user drop rates from version {} to {}", userVersion, bundledVersion);

		backupUserConfig(userVersion);

		JsonObject v1Root = loadV1Rates();

		JsonObject migrated = mergeUserCustomizations(userRoot, v1Root, bundledRoot);

		try (OutputStreamWriter writer = new OutputStreamWriter(new FileOutputStream(userConfigFile), StandardCharsets.UTF_8))
		{
			gson.toJson(migrated, writer);
			log.info("Successfully migrated user drop rates to version {}", bundledVersion);
		}
		catch (Exception e)
		{
			log.warn("Failed to save migrated drop rates config: {}", e.getMessage());
		}
	}

	/**
	 * Create backup files of the user configuration before migrating
	 */
	private void backupUserConfig(int oldVersion)
	{
		try
		{
			File parentDir = userConfigFile.getParentFile();
			if (parentDir != null && parentDir.exists())
			{
				File versionedBackup = new File(parentDir, "drop_rates.json.v" + oldVersion + ".bak");
				Files.copy(userConfigFile.toPath(), versionedBackup.toPath(), StandardCopyOption.REPLACE_EXISTING);
				File genericBackup = new File(parentDir, "drop_rates.json.bak");
				Files.copy(userConfigFile.toPath(), genericBackup.toPath(), StandardCopyOption.REPLACE_EXISTING);
				log.info("Created backup of user drop rates at {}", genericBackup.getAbsolutePath());
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to create backup of user drop rates: {}", e.getMessage());
		}
	}

	/**
	 * Load historical v1 rates from bundled resource to detect customizations
	 */
	private JsonObject loadV1Rates()
	{
		try (InputStream is = getClass().getResourceAsStream("/drop_rates_v1.json"))
		{
			if (is != null)
			{
				try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
				{
					return gson.fromJson(reader, JsonObject.class);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load v1 reference drop rates: {}", e.getMessage());
		}
		return null;
	}

	/**
	 * Merge intentional user customizations onto new bundled defaults
	 */
	private JsonObject mergeUserCustomizations(JsonObject userRoot, JsonObject v1Root, JsonObject bundledRoot)
	{
		JsonObject migrated = bundledRoot.deepCopy();
		JsonObject userShipwrecks = userRoot.getAsJsonObject("shipwrecks");
		JsonObject v1Shipwrecks = v1Root != null ? v1Root.getAsJsonObject("shipwrecks") : null;
		JsonObject migratedShipwrecks = migrated.getAsJsonObject("shipwrecks");

		if (userShipwrecks != null && migratedShipwrecks != null)
		{
			for (String shipwreckKey : userShipwrecks.keySet())
			{
				JsonObject userSw = userShipwrecks.getAsJsonObject(shipwreckKey);
				JsonObject userItems = userSw != null ? userSw.getAsJsonObject("items") : null;
				if (userItems == null)
				{
					continue;
				}

				JsonObject v1Sw = v1Shipwrecks != null ? v1Shipwrecks.getAsJsonObject(shipwreckKey) : null;
				JsonObject v1Items = v1Sw != null ? v1Sw.getAsJsonObject("items") : null;

				JsonObject migratedSw = migratedShipwrecks.getAsJsonObject(shipwreckKey);
				if (migratedSw == null)
				{
					migratedShipwrecks.add(shipwreckKey, userSw.deepCopy());
					continue;
				}

				JsonObject migratedItems = migratedSw.getAsJsonObject("items");
				if (migratedItems == null)
				{
					migratedItems = new JsonObject();
					migratedSw.add("items", migratedItems);
				}

				for (String itemName : userItems.keySet())
				{
					JsonElement userRateEl = userItems.get(itemName);
					if (userRateEl == null || !userRateEl.isJsonPrimitive())
					{
						continue;
					}
					double userRate = userRateEl.getAsDouble();

					JsonElement v1RateEl = v1Items != null ? v1Items.get(itemName) : null;
					if (v1RateEl == null && v1Items != null)
					{
						if (itemName.contains(" (unf)"))
						{
							v1RateEl = v1Items.get(itemName.replace(" (unf)", "(unf)"));
						}
						else if (itemName.contains("(unf)"))
						{
							v1RateEl = v1Items.get(itemName.replace("(unf)", " (unf)"));
						}
					}

					String canonicalName = "Adamant bolts(unf)".equalsIgnoreCase(itemName) ? "Adamant bolts (unf)" : itemName;

					if (v1RateEl != null && v1RateEl.isJsonPrimitive())
					{
						double v1Rate = v1RateEl.getAsDouble();
						if (Math.abs(userRate - v1Rate) > 1e-9)
						{
							if (!canonicalName.equals(itemName))
							{
								migratedItems.remove(itemName);
							}
							migratedItems.addProperty(canonicalName, userRate);
							log.info("Preserving custom user drop rate for '{}' in {}: {}", canonicalName, shipwreckKey, userRate);
						}
					}
					else
					{
						if (!canonicalName.equals(itemName))
						{
							migratedItems.remove(itemName);
						}
						migratedItems.addProperty(canonicalName, userRate);
						log.info("Preserving custom user drop item '{}' in {}: {}", canonicalName, shipwreckKey, userRate);
					}
				}
			}
		}

		return migrated;
	}

	/**
	 * Load rates from user config file
	 */
	private void loadUserRates()
	{
		try (InputStreamReader reader = new InputStreamReader(new FileInputStream(userConfigFile), StandardCharsets.UTF_8))
		{
			parseDropRates(reader);
			log.info("Loaded user drop rates from {}", userConfigFile.getAbsolutePath());
		}
		catch (Exception e)
		{
			log.warn("Failed to load user drop rates: {}", e.getMessage());
		}
	}

	/**
	 * Copy bundled config to user directory
	 */
	private void copyBundledToUser()
	{
		try (InputStream is = getClass().getResourceAsStream("/drop_rates.json"))
		{
			if (is != null)
			{
				File parentDir = userConfigFile.getParentFile();
				if (parentDir != null && !parentDir.exists() && !parentDir.mkdirs())
				{
					log.warn("Failed to create directory: {}", parentDir.getAbsolutePath());
					return;
				}
				try (FileOutputStream fos = new FileOutputStream(userConfigFile))
				{
					byte[] buffer = new byte[1024];
					int bytesRead;
					while ((bytesRead = is.read(buffer)) != -1)
					{
						fos.write(buffer, 0, bytesRead);
					}
				}
				log.info("Copied drop rates config to {}", userConfigFile.getAbsolutePath());
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to copy drop rates config: {}", e.getMessage());
		}
	}

	/**
	 * Parse drop rates from a reader
	 */
	private void parseDropRates(Reader reader)
	{
		JsonObject root = gson.fromJson(reader, JsonObject.class);
		parseDropRatesFromObject(root);
	}

	/**
	 * Parse drop rates from a JsonObject
	 */
	private void parseDropRatesFromObject(JsonObject root)
	{
		if (root == null)
		{
			return;
		}

		JsonObject shipwrecks = root.getAsJsonObject("shipwrecks");
		if (shipwrecks == null)
		{
			return;
		}

		for (String shipwreckKey : shipwrecks.keySet())
		{
			try
			{
				ShipwreckType type = ShipwreckType.valueOf(shipwreckKey);
				JsonObject shipwreckData = shipwrecks.getAsJsonObject(shipwreckKey);
				JsonObject items = shipwreckData.getAsJsonObject("items");

				if (items != null)
				{
					Map<String, Double> itemRates = dropRates.computeIfAbsent(type, k -> new HashMap<>());
					Map<String, Double> displayRates = displayItemRates.computeIfAbsent(type, k -> new LinkedHashMap<>());

					Map<String, Double> sourceRates = new HashMap<>();
					for (String itemName : items.keySet())
					{
						JsonElement rateElement = items.get(itemName);
						if (rateElement != null && rateElement.isJsonPrimitive())
						{
							sourceRates.put(itemName.toLowerCase().trim(), rateElement.getAsDouble());
							displayRates.put(itemName, rateElement.getAsDouble());
						}
					}

					for (Map.Entry<String, Double> entry : sourceRates.entrySet())
					{
						String lowerKey = entry.getKey();
						double rate = entry.getValue();

						itemRates.put(lowerKey, rate);

						if (lowerKey.contains(" (unf)"))
						{
							String alias = lowerKey.replace(" (unf)", "(unf)");
							if (!sourceRates.containsKey(alias))
							{
								itemRates.put(alias, rate);
							}
						}
						else if (lowerKey.contains("(unf)"))
						{
							String alias = lowerKey.replace("(unf)", " (unf)");
							if (!sourceRates.containsKey(alias))
							{
								itemRates.put(alias, rate);
							}
						}
					}
				}
			}
			catch (IllegalArgumentException e)
			{
				log.debug("Unknown shipwreck type in config: {}", shipwreckKey);
			}
		}
	}

	/**
	 * Get the expected drop rate for an item from a specific shipwreck type
	 * @param shipwreckType The type of shipwreck
	 * @param itemName The name of the item
	 * @return The expected drop rate (0.0 to 1.0), or 0.0 if unknown
	 */
	public double getExpectedDropRate(ShipwreckType shipwreckType, String itemName)
	{
		if (itemName == null)
		{
			return 0.0;
		}

		Map<String, Double> itemRates = dropRates.get(shipwreckType);
		if (itemRates == null)
		{
			log.debug("No rates found for shipwreck type: {}", shipwreckType);
			return 0.0;
		}

		String key = itemName.toLowerCase().trim();
		Double rate = itemRates.get(key);
		if (rate == null)
		{
			if (key.contains(" (unf)"))
			{
				rate = itemRates.get(key.replace(" (unf)", "(unf)"));
			}
			else if (key.contains("(unf)"))
			{
				rate = itemRates.get(key.replace("(unf)", " (unf)"));
			}
		}

		double result = rate != null ? rate : 0.0;
		return result;
	}

	/**
	 * Get all expected drop rates with original display item names for a shipwreck type
	 * @param shipwreckType The type of shipwreck
	 * @return An unmodifiable map of item name -> expected drop rate
	 */
	public Map<String, Double> getAllItemRates(ShipwreckType shipwreckType)
	{
		Map<String, Double> rates = displayItemRates.get(shipwreckType);
		if (rates == null)
		{
			return Collections.emptyMap();
		}
		return Collections.unmodifiableMap(rates);
	}
}

package com.salvagesack;

import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Manages fetching and caching of item icons using RuneLite's ItemManager
 */
@Slf4j
public class ItemIconManager
{
	private static final int ICON_SIZE = 32;

	private final Map<Integer, BufferedImage> iconCache;
	private final BufferedImage placeholderIcon;

	@Setter
	private Runnable onIconLoaded;

	@Setter
	private ItemManager itemManager;

	public ItemIconManager()
	{
		this.iconCache = new ConcurrentHashMap<>();
		this.placeholderIcon = createPlaceholderIcon();
	}

	/**
	 * Get icon for an item by ID
	 * @param itemId ID of the item
	 * @return BufferedImage of the item icon, or placeholder if not found
	 */
	public BufferedImage getItemIcon(int itemId)
	{
		if (itemId <= 0)
		{
			return placeholderIcon;
		}

		// Check cache first
		BufferedImage cached = iconCache.get(itemId);
		if (cached != null)
		{
			return cached;
		}

		// Try to get from ItemManager
		if (itemManager != null)
		{
			try
			{
				AsyncBufferedImage asyncImage = itemManager.getImage(itemId);
				if (asyncImage != null)
				{
					// Cache when the image loads and trigger callback
					asyncImage.onLoaded(() -> {
						iconCache.put(itemId, asyncImage);
						log.debug("Cached icon for item {}", itemId);
						if (onIconLoaded != null)
						{
							onIconLoaded.run();
						}
					});
					// Return the async image (it extends BufferedImage)
					return asyncImage;
				}
			}
			catch (Exception e)
			{
				log.debug("Failed to get icon for item {}: {}", itemId, e.getMessage());
			}
		}

		// Return placeholder if fetch failed
		return placeholderIcon;
	}

	/**
	 * Create a simple placeholder icon
	 */
	private BufferedImage createPlaceholderIcon()
	{
		BufferedImage image = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
		// Create a simple gray square
		for (int x = 0; x < ICON_SIZE; x++)
		{
			for (int y = 0; y < ICON_SIZE; y++)
			{
				if (x < 2 || x >= ICON_SIZE - 2 || y < 2 || y >= ICON_SIZE - 2)
				{
					image.setRGB(x, y, 0xFF666666); // Border
				}
				else
				{
					image.setRGB(x, y, 0xFF333333); // Fill
				}
			}
		}
		return image;
	}
}

package com.salvagesack;

import lombok.Data;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

/**
 * Stores all salvage tracking data for a specific shipwreck type.
 * <p>
 * Each shipwreck type maintains its own loot statistics including total sorts,
 * individual item drop counts, and a timestamp for UI ordering.
 * </p>
 * <p>
 * The panel displays shipwreck sections sorted by {@link #lastUpdated} so that
 * the most recently active shipwreck always appears at the top, regardless of
 * whether it is expanded or collapsed.
 * </p>
 */
@Data
public class SalvageData
{
	private final ShipwreckType shipwreckType;
	private int totalLoots;
	private final Map<Integer, SalvageItem> items; // itemId -> SalvageItem

	/**
	 * Timestamp (milliseconds since epoch) of the last loot recorded for this shipwreck.
	 * Used to sort shipwreck panels in the UI with most recently updated at the top.
	 */
	private long lastUpdated;

	public SalvageData(ShipwreckType shipwreckType)
	{
		this.shipwreckType = shipwreckType;
		this.totalLoots = 0;
		this.items = new ConcurrentHashMap<>();
		this.lastUpdated = 0;
	}

	/**
	 * Constructor for deserialization
	 */
	public SalvageData(ShipwreckType shipwreckType, int totalLoots, Map<Integer, SalvageItem> items)
	{
		this.shipwreckType = shipwreckType;
		this.totalLoots = totalLoots;
		this.items = items;
		this.lastUpdated = 0;
	}

	/**
	 * Record a loot drop
	 * @param itemId The item ID that was looted
	 * @param itemName The item name
	 * @param expectedDropRate Expected drop rate for this item
	 */
	public void recordLoot(int itemId, String itemName, double expectedDropRate)
	{
		recordLoot(itemId, itemName, expectedDropRate, 1);
	}

	/**
	 * Record a loot drop with quantity
	 * Counts as 1 drop for rate calculation, but tracks full quantity
	 * @param itemId The item ID that was looted
	 * @param itemName The item name
	 * @param expectedDropRate Expected drop rate for this item
	 * @param quantity Number of items looted (for display, not rate calc)
	 */
	public synchronized void recordLoot(int itemId, String itemName, double expectedDropRate, int quantity)
	{
		SalvageItem existingSameName = null;
		for (Map.Entry<Integer, SalvageItem> entry : items.entrySet())
		{
			if (entry.getKey() != itemId && isSameItemName(entry.getValue().getItemName(), itemName))
			{
				existingSameName = entry.getValue();
				items.remove(entry.getKey());
				break;
			}
		}

		SalvageItem item = items.get(itemId);
		if (item != null && existingSameName != null)
		{
			item.setDropCount(item.getDropCount() + existingSameName.getDropCount());
			item.setTotalQuantity(item.getTotalQuantity() + existingSameName.getTotalQuantity());
		}
		else if (item == null && existingSameName != null)
		{
			int fallbackHash = itemName.hashCode() & 0x7FFFFFFF;
			if (itemId == fallbackHash)
			{
				item = existingSameName;
				items.put(item.getItemId(), item);
			}
			else
			{
				item = existingSameName;
				item.setItemId(itemId);
				items.put(itemId, item);
			}
		}
		else if (item == null)
		{
			item = new SalvageItem(itemId, itemName, expectedDropRate);
			items.put(itemId, item);
		}

		if (expectedDropRate > 0)
		{
			item.setExpectedDropRate(expectedDropRate);
		}
		item.recordDrop(quantity);  // 1 drop for rate, full quantity for display
	}

	/**
	 * Normalizes item IDs using the provided lookup function to ensure legacy items
	 * (e.g. keyed by hash-fallback) are re-keyed to their canonical item IDs.
	 * Merges drop counts and quantities if multiple entries map to the same ID.
	 *
	 * @param idLookup Lookup function mapping item name to canonical item ID
	 * @return true if any item was re-keyed or merged, false otherwise
	 */
	public synchronized boolean normalizeItemIds(Function<String, Integer> idLookup)
	{
		if (idLookup == null || items.isEmpty())
		{
			return false;
		}

		boolean modified = false;
		Map<Integer, SalvageItem> normalized = new ConcurrentHashMap<>();

		for (SalvageItem item : items.values())
		{
			int lookupId = idLookup.apply(item.getItemName());
			int fallbackHash = item.getItemName().hashCode() & 0x7FFFFFFF;

			int canonicalId;
			if (lookupId <= 0 || lookupId == fallbackHash)
			{
				canonicalId = item.getItemId();
			}
			else
			{
				canonicalId = lookupId;
			}

			if (canonicalId != item.getItemId())
			{
				modified = true;
				item.setItemId(canonicalId);
			}

			SalvageItem existing = normalized.get(canonicalId);
			if (existing != null)
			{
				existing.setDropCount(existing.getDropCount() + item.getDropCount());
				existing.setTotalQuantity(existing.getTotalQuantity() + item.getTotalQuantity());
				if (item.getExpectedDropRate() > 0 && existing.getExpectedDropRate() <= 0)
				{
					existing.setExpectedDropRate(item.getExpectedDropRate());
				}
				modified = true;
			}
			else
			{
				normalized.put(canonicalId, item);
			}
		}

		if (modified)
		{
			items.clear();
			items.putAll(normalized);
		}

		return modified;
	}

	/**
	 * Increment total loot count and update the last modified timestamp.
	 * <p>
	 * This method should be called once per salvage sort action. The timestamp
	 * update ensures this shipwreck type will be displayed at the top of the
	 * panel, as shipwrecks are sorted by most recently updated.
	 * </p>
	 */
	public void incrementTotalLoots()
	{
		this.totalLoots++;
		this.lastUpdated = System.currentTimeMillis();
	}

	private static boolean isSameItemName(String name1, String name2)
	{
		if (name1 == null || name2 == null)
		{
			return false;
		}
		if (name1.equalsIgnoreCase(name2))
		{
			return true;
		}
		String n1 = name1.toLowerCase().replace(" (unf)", "(unf)").trim();
		String n2 = name2.toLowerCase().replace(" (unf)", "(unf)").trim();
		return n1.equalsIgnoreCase(n2);
	}
}

package com.salvagesack;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Handles persistence of salvage tracking data between sessions using RSProfile configuration.
 * <p>
 * On first load, checks for existing file-based data and migrates it to the RSProfile format.
 * This ensures backwards compatibility with previous plugin versions.
 * </p>
 */
@Slf4j
public class SalvageDataManager
{
	private static final String CONFIG_GROUP = "salvagesack";
	private static final String DATA_KEY = "salvageData";
	private static final String DATA_FILE = "salvage-data.json";

	private final Gson gson;
	private final ConfigManager configManager;
	private final File legacyDataFile;

	/**
	 * Create a SalvageDataManager using RSProfile configuration for persistence.
	 *
	 * @param configManager RuneLite's ConfigManager for RSProfile storage
	 * @param legacyDataDirectory Directory where legacy file-based data may exist (for migration)
	 * @param gson Gson instance for JSON serialization
	 */
	public SalvageDataManager(ConfigManager configManager, File legacyDataDirectory, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.legacyDataFile = legacyDataDirectory != null ? new File(legacyDataDirectory, DATA_FILE) : null;
	}

	/**
	 * Save salvage data to RSProfile configuration
	 */
	public void saveData(Map<ShipwreckType, SalvageData> dataMap)
	{
		SaveDataWrapper wrapper = new SaveDataWrapper();
		wrapper.shipwrecks = new HashMap<>();

		for (Map.Entry<ShipwreckType, SalvageData> entry : dataMap.entrySet())
		{
			wrapper.shipwrecks.put(entry.getKey().name(), SalvageDataDto.fromSalvageData(entry.getValue()));
		}

		String jsonData = gson.toJson(wrapper);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, DATA_KEY, jsonData);
		log.debug("Saved salvage data to RSProfile configuration");
	}

	/**
	 * Load salvage data from RSProfile configuration.
	 * If no RSProfile data exists, attempts to migrate from legacy file format.
	 */
	public Map<ShipwreckType, SalvageData> loadData()
	{
		String jsonData = configManager.getRSProfileConfiguration(CONFIG_GROUP, DATA_KEY);

		if (jsonData != null && !jsonData.isEmpty())
		{
			Map<ShipwreckType, SalvageData> dataMap = parseJsonData(jsonData);
			if (dataMap == null)
			{
				return null;
			}
			if (!dataMap.isEmpty())
			{
				log.debug("Loaded salvage data from RSProfile configuration");
				return dataMap;
			}
		}

		Map<ShipwreckType, SalvageData> legacyData = loadLegacyData();
		if (legacyData == null)
		{
			return null;
		}
		if (!legacyData.isEmpty())
		{
			String existingData = configManager.getRSProfileConfiguration(CONFIG_GROUP, DATA_KEY);
			if (existingData != null && !existingData.isEmpty())
			{
				log.info("RSProfile data appeared during migration check, using RSProfile data");
				return parseJsonData(existingData);
			}

			log.info("Migrating legacy file data to RSProfile configuration");
			saveData(legacyData);
			renameLegacyFile();
			return legacyData;
		}

		log.debug("No saved data found, starting fresh");
		return new HashMap<>();
	}

	/**
	 * Parse JSON data into a salvage data map
	 */
	private Map<ShipwreckType, SalvageData> parseJsonData(String jsonData)
	{
		Map<ShipwreckType, SalvageData> dataMap = new HashMap<>();

		try
		{
			SaveDataWrapper wrapper = gson.fromJson(jsonData, SaveDataWrapper.class);

			if (wrapper != null && wrapper.shipwrecks != null)
			{
				for (Map.Entry<String, SalvageDataDto> entry : wrapper.shipwrecks.entrySet())
				{
					try
					{
						ShipwreckType type = ShipwreckType.valueOf(entry.getKey());
						SalvageData data = entry.getValue().toSalvageData(type);
						dataMap.put(type, data);
					}
					catch (IllegalArgumentException e)
					{
						log.warn("Unknown shipwreck type: {}", entry.getKey());
					}
				}
			}
		}
		catch (Exception e)
		{
			log.error("Failed to parse salvage data JSON", e);
			return null;
		}

		return dataMap;
	}

	/**
	 * Load data from legacy file-based storage (for migration)
	 */
	private Map<ShipwreckType, SalvageData> loadLegacyData()
	{
		Map<ShipwreckType, SalvageData> dataMap = new HashMap<>();

		if (legacyDataFile == null || !legacyDataFile.exists())
		{
			return dataMap;
		}

		try (InputStreamReader reader = new InputStreamReader(new FileInputStream(legacyDataFile), StandardCharsets.UTF_8))
		{
			SaveDataWrapper wrapper = gson.fromJson(reader, SaveDataWrapper.class);

			if (wrapper != null && wrapper.shipwrecks != null)
			{
				for (Map.Entry<String, SalvageDataDto> entry : wrapper.shipwrecks.entrySet())
				{
					try
					{
						ShipwreckType type = ShipwreckType.valueOf(entry.getKey());
						SalvageData data = entry.getValue().toSalvageData(type);
						dataMap.put(type, data);
					}
					catch (IllegalArgumentException e)
					{
						log.warn("Unknown shipwreck type: {}", entry.getKey());
					}
				}
			}

			log.info("Loaded {} shipwreck types from legacy file: {}", dataMap.size(), legacyDataFile.getAbsolutePath());
		}
		catch (Exception e)
		{
			log.error("Failed to load legacy salvage data file", e);
			return null;
		}

		return dataMap;
	}

	/**
	 * Rename the legacy file to indicate migration is complete
	 */
	private void renameLegacyFile()
	{
		if (legacyDataFile == null || !legacyDataFile.exists())
		{
			return;
		}

		File migratedFile = new File(legacyDataFile.getParentFile(), DATA_FILE + ".migrated");
		try
		{
			Files.move(legacyDataFile.toPath(), migratedFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
			log.info("Renamed legacy file to {} to indicate migration complete", migratedFile.getName());
		}
		catch (IOException e)
		{
			log.warn("Failed to rename legacy file: {}. Data was migrated successfully, but " +
					"the old file remains and may be re-read on next startup.", e.getMessage());
		}
	}

	/**
	 * Wrapper class for the root JSON object
	 */
	private static class SaveDataWrapper
	{
		Map<String, SalvageDataDto> shipwrecks;
	}

	/**
	 * Data Transfer Object for serialization
	 */
	private static class SalvageDataDto
	{
		int totalLoots;
		long lastUpdated;
		Map<String, SalvageItemDto> items;

		static SalvageDataDto fromSalvageData(SalvageData data)
		{
			SalvageDataDto dto = new SalvageDataDto();
			dto.totalLoots = data.getTotalLoots();
			dto.lastUpdated = data.getLastUpdated();
			dto.items = new HashMap<>();

			synchronized (data)
			{
				for (Map.Entry<Integer, SalvageItem> entry : data.getItems().entrySet())
				{
					dto.items.put(String.valueOf(entry.getKey()), SalvageItemDto.fromSalvageItem(entry.getValue()));
				}
			}

			return dto;
		}

		SalvageData toSalvageData(ShipwreckType type)
		{
			Map<Integer, SalvageItem> itemsMap = new ConcurrentHashMap<>();

			if (items != null)
			{
				for (Map.Entry<String, SalvageItemDto> entry : items.entrySet())
				{
					try
					{
						int itemId = Integer.parseInt(entry.getKey());
						SalvageItem item = entry.getValue().toSalvageItem(itemId);
						itemsMap.put(itemId, item);
					}
					catch (NumberFormatException e)
					{
						log.warn("Invalid item ID format: {}", entry.getKey());
					}
				}
			}

			SalvageData salvageData = new SalvageData(type, totalLoots, itemsMap);
			salvageData.setLastUpdated(lastUpdated);
			return salvageData;
		}
	}

	/**
	 * Data Transfer Object for SalvageItem
	 */
	private static class SalvageItemDto
	{
		String itemName;
		int dropCount;
		int totalQuantity;
		double expectedDropRate;

		static SalvageItemDto fromSalvageItem(SalvageItem item)
		{
			SalvageItemDto dto = new SalvageItemDto();
			dto.itemName = item.getItemName();
			dto.dropCount = item.getDropCount();
			dto.totalQuantity = item.getTotalQuantity();
			dto.expectedDropRate = item.getExpectedDropRate();
			return dto;
		}

		SalvageItem toSalvageItem(int itemId)
		{
			int qty = totalQuantity > 0 ? totalQuantity : dropCount;
			return new SalvageItem(itemId, itemName, dropCount, qty, expectedDropRate);
		}
	}
}

package com.salvagesack;

import lombok.Data;

/**
 * Represents a salvage item drop with tracking information
 */
@Data
public class SalvageItem
{
	private int itemId;
	private final String itemName;
	private int dropCount;      // Number of times this item was dropped (for rate calculation)
	private int totalQuantity;  // Total quantity received (for display)
	private double expectedDropRate; // Expected rate from wiki (e.g., 0.1 for 10%)

	public SalvageItem(int itemId, String itemName, double expectedDropRate)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.dropCount = 0;
		this.totalQuantity = 0;
		this.expectedDropRate = expectedDropRate;
	}


	/**
	 * Full constructor for deserialization with quantity
	 */
	public SalvageItem(int itemId, String itemName, int dropCount, int totalQuantity, double expectedDropRate)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.dropCount = dropCount;
		this.totalQuantity = totalQuantity;
		this.expectedDropRate = expectedDropRate;
	}

	/**
	 * Increment the drop count for this item (single drop)
	 */
	public void incrementDropCount()
	{
		this.dropCount++;
		this.totalQuantity++;
	}

	/**
	 * Record a drop with a specific quantity
	 * Counts as 1 drop for rate calculation, but adds full quantity to total
	 * @param quantity The quantity received in this drop
	 */
	public void recordDrop(int quantity)
	{
		this.dropCount++;           // Only 1 drop for rate calculation
		this.totalQuantity += quantity;  // Full quantity for display
	}

	/**
	 * Add to the drop count for this item (legacy method)
	 * @param amount Amount to add
	 * @deprecated Use recordDrop(quantity) instead
	 */
	@Deprecated
	public void addDropCount(int amount)
	{
		this.dropCount += amount;
		this.totalQuantity += amount;
	}

	/**
	 * Calculate current drop rate based on total loots
	 * @param totalLoots Total number of loots from this shipwreck type
	 * @return Current drop rate as a decimal (e.g., 0.15 for 15%)
	 */
	public double getCurrentDropRate(int totalLoots)
	{
		if (totalLoots == 0)
		{
			return 0.0;
		}
		return (double) dropCount / totalLoots;
	}
}

