		SalvageSackPlugin plugin = new SalvageSackPlugin();
		assertEquals(ItemID.BOAT_BOTTLE_EMPTY, plugin.lookupItemId("Boat bottle (empty)"));
		assertEquals(ItemID.BOAT_BOTTLE_EMPTY, plugin.lookupItemId("boat bottle (empty)"));
