		Map<ShipwreckType, SalvageData> dataMap = new HashMap<>();
		panel.updateData(dataMap);

		// Initially with no data, inactive shipwreck types should be collapsed
		assertFalse(panel.isExpanded(ShipwreckType.SMALL));
